mod data;

use askama::Template;
use data::{
    PATH_ROOT,
    language::{DEFAULT_LANGUAGE, LANGUAGES_SUPPORTED, all_languages},
    monsters::load_monsters,
    weapons::load_weapons,
};
use serde_json::json;
use std::{fs, io, path::Path};

const PATH_STATIC_FILES: &str = "static";
const PATH_OUTPUT: &str = "dist";
const PATH_ASSETS: &str = "assets";
/// Generated by Tailwind, not tracked in git.
const PATH_STYLESHEET: &str = "css/main.css";

#[derive(Template)]
#[template(path = "pages/index.html")]
struct IndexPage<'a> {
    /// Initial values only; Alpine switches both to the stored language.
    lang: &'a str,
    title: &'a str,
    languages: &'a [&'a str],
    data: String,
}

/// Build the static site into `dist/`.
fn main() {
    let root = Path::new(PATH_ROOT);
    let stylesheet = root.join(PATH_STATIC_FILES).join(PATH_STYLESHEET);
    assert!(
        stylesheet.exists(),
        "Missing {}! Build the CSS first, e.g. `devenv shell -- build`.",
        stylesheet.display()
    );

    let languages = all_languages();
    let title = languages
        .get(DEFAULT_LANGUAGE)
        .and_then(|dictionary| dictionary["title"].as_str())
        .expect("Missing title in the default language!");

    let data = json!({
        "monsters": load_monsters(),
        "weapons": load_weapons(),
        "languages": &languages,
    })
    .to_string()
    // Keep the embedded JSON from closing its <script> tag.
    .replace("</", "<\\/");

    let page = IndexPage {
        lang: DEFAULT_LANGUAGE,
        title,
        languages: &LANGUAGES_SUPPORTED,
        data,
    };
    let html = page
        .render()
        .unwrap_or_else(|e| panic!("Could not render the index page!\n{}", e));

    let output = root.join(PATH_OUTPUT);
    if output.exists() {
        fs::remove_dir_all(&output).expect("Could not clean the output dir!");
    }
    fs::create_dir_all(&output).expect("Could not create the output dir!");

    fs::write(output.join("index.html"), html)
        .expect("Could not write index.html!");
    fs::write(output.join(".nojekyll"), "")
        .expect("Could not write .nojekyll!");
    copy_dir(&root.join(PATH_STATIC_FILES), &output.join(PATH_ASSETS))
        .expect("Could not copy the static files!");

    println!("Site built into {}", output.display());
}

/// Copy a directory recursively.
fn copy_dir(from: &Path, to: &Path) -> io::Result<()> {
    fs::create_dir_all(to)?;

    for entry in fs::read_dir(from)? {
        let entry = entry?;
        let target = to.join(entry.file_name());

        if entry.file_type()?.is_dir() {
            copy_dir(&entry.path(), &target)?;
        } else {
            fs::copy(entry.path(), target)?;
        }
    }

    Ok(())
}
